int n = 5_000_000;
long t0 = System.nanoTime();
List<Integer> boxed = new ArrayList<>(n);
for (int i = 0; i < n; i++) boxed.add(i);
long t1 = System.nanoTime();
int[] prim = new int[n];
for (int i = 0; i < n; i++) prim[i] = i;
long t2 = System.nanoTime();
System.out.println("boxed ms=" + (t1 - t0) / 1_000_000 + " primitive ms=" + (t2 - t1) / 1_000_000);

// OUTPUT: (varies)
// boxed ms=95 primitive ms=6

class Lru<K, V> extends LinkedHashMap<K, V> {
    private final int cap;
    Lru(int cap) {
        super(16, 0.75f, true);
        this.cap = cap;
    }
    @Override protected boolean removeEldestEntry(Map.Entry<K, V> e) { return size() > cap; }
}
Lru<String, Integer> c = new Lru<>(2);
c.put("a", 1);
c.put("b", 2);
c.get("a");
c.put("c", 3);
System.out.println(c.keySet());

// OUTPUT:
// [a, c]

import java.util.ArrayList;

public class ArrayListBasics { // class that holds the main method
    public static void main(String[] args) { // program entry point
        ArrayList<String> list = new ArrayList<>(); // creates an empty ArrayList named list

        // Adding elements
        list.add("Java");
        list.add("Python");
        list.add("C++");
        list.add("Java");  // duplicate allowed
        list.add(null);     // null allowed

        System.out.println("ArrayList: " + list);
        System.out.println("Size: " + list.size());

        // Accessing elements
        System.out.println("Element at index 1: " + list.get(1));

        // Modifying elements
        list.set(2, "JavaScript"); // replaces the third element (index 2)
        System.out.println("After set: " + list);

        // Removing elements
        list.remove("Java");  // removes first occurrence
        list.remove(0);       // removes by index
        System.out.println("After remove: " + list);

        // Checking elements
        System.out.println("Contains Python? " + list.contains("Python"));
    }
}

