static int depth(Node root) {
    Deque<Node> st = new ArrayDeque<>();
    Deque<Integer> d = new ArrayDeque<>();
    st.push(root);
    d.push(1);
    int max = 0;
    while (!st.isEmpty()) {
        Node n = st.pop();
        int cur = d.pop();
        max = Math.max(max, cur);
        if (n.left != null) {
            st.push(n.left);
            d.push(cur + 1);
        }
        if (n.right != null) {
            st.push(n.right);
            d.push(cur + 1);
        }
    }
    return max;
}

// OUTPUT:
// the tree depth is computed without recursion, safe for deep trees

